typedef struct node { int value; struct node *next; } node;

/* coalgebra: seed -> one allocated layer, or NULL (base case / no memory). */
static node *unfold(int seed) {
    if (seed <= 0) return NULL;          /* stop condition */
    node *n = malloc(sizeof *n);
    if (!n) return NULL;                 /* allocation failure also stops the unfold */
    n->value = seed;
    n->next = unfold(seed / 2);          /* corecursive step: next seed */
    return n;
}
